Section Stage.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (IL : icpt_layout) (HI : asan_iface).
Hypothesis LY : PMA.layout L C.
Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Hypothesis ICok : aicpt_ok L ar IL SCFG HI.
Hypothesis ILY : as0_icpt_layout IL.
Let LYa := PMA.ly_as0 L C LY.

Theorem long_c : PMA.opnew_spec L ar HI -> forall (fx : FPState) R0 M0 model0 K LB FF LK0 Aw0 cr ois os sp r c0 n p0 b R2 M2 model2 LK2 Aw2 (l : list Z),
    PMAIS.pre L ar HI R0 M0 model0 K LB FF LK0 Aw0 cr ois os sp r (PM.VLong c0 n p0) b ->
    PEACIS2.kont_c L ar HI R0 M0 model0 K LB FF LK0 Aw0 cr ois sp r (PM.VLong c0 n p0) b l ->
    Z.of_nat (length l) = n -> L5.bytes_at RSEGS M0 p0 l ->
    PMAIS.mid2 L ar HI R0 M0 model0 LB FF LK0 Aw0 cr ois os sp (PM.VLong c0 n p0) b R2 M2 model2 LK2 Aw2 ->
    srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx) R2 0xaa8e0 M2 model2) K.
Proof.
Ltac a64 AG X Ms := apply (L5C.u64_at_agree RSEGS Ms); [intros i Hi; apply AG; (lia || fail 1 "AG")| (lia || fail 1 "B1")| (lia || fail 1 "B2")| exact X].
